import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { HttpClient } from '@angular/common/http';

interface Vehicle {
  tipo: string;
  cantidad: number;
  uniformes: string[];
  armamento: string[]; // ⬅️ NUEVO: Array de armamento
}

interface Uniform {
  nombre: string;
  descripcion: string;
  precio: number;
  imagen: string;
}

interface Armamento {
  tipo: string;
  descripcion: string;
  calibre?: string;
  imagen: string;
}

@Component({
  selector: 'app-proteccion-ejecutiva',
  standalone: true,
  imports: [CommonModule, FormsModule, ReactiveFormsModule],
  templateUrl: './proteccion-ejecutiva.component.html',
  styleUrls: ['./proteccion-ejecutiva.component.scss']
})
export class ProteccionEjecutivaComponent {
  
  // ============================================
  // PROPIEDADES DE VEHÍCULOS
  // ============================================
  vehicleTypes = [
    { 
      tipo: 'Sedan', 
      categoria: 'Ejecutivo',
      capacidad: 4,
      descripcion: 'Vehículo blindado nivel B4-B6',
      imagen: '🚗',
      tripulacion: 2 // conductor + escolta
    },
    { 
      tipo: 'SUV', 
      categoria: 'Versátil',
      capacidad: 6,
      descripcion: 'Todo terreno blindado B4-B6',
      imagen: '🚙',
      tripulacion: 3 // conductor + 2 escoltas
    },
    { 
      tipo: 'Todo Terreno', 
      categoria: 'Extremo',
      capacidad: 5,
      descripcion: 'Protección nivel B6-B7',
      imagen: '🚐',
      tripulacion: 4 // conductor + 3 escoltas
    },
    { 
      tipo: 'Camioneta', 
      categoria: 'Operativo',
      capacidad: 5,
      descripcion: 'Unidad táctica blindada',
      imagen: '🛻',
      tripulacion: 3 // conductor + 2 escoltas
    },
    { 
      tipo: 'Hatchback', 
      categoria: 'Urbano',
      capacidad: 4,
      descripcion: 'Discreto para ciudad B4',
      imagen: '🚗',
      tripulacion: 2 // conductor + escolta
    },
    { 
      tipo: 'Motocicleta', 
      categoria: 'Táctica',
      capacidad: 1,
      descripcion: 'Movilidad rápida',
      imagen: '🏍️',
      tripulacion: 1 // solo conductor
    },
    { 
      tipo: 'Helicóptero', 
      categoria: 'Aéreo',
      capacidad: 4,
      descripcion: 'Transporte ejecutivo aéreo',
      imagen: '🚁',
      tripulacion: 2 // piloto + copiloto
    }
  ];

  vehicleCounts: { [key: string]: number } = {
    'Sedan': 0,
    'SUV': 0,
    'Todo Terreno': 0,
    'Camioneta': 0,
    'Hatchback': 0,
    'Motocicleta': 0,
    'Helicóptero': 0
  };

  selectedVehicles: Vehicle[] = [];

  // ============================================
  // UNIFORMES
  // ============================================
  uniformes: Uniform[] = [
    {
      nombre: 'Uniforme Ejecutivo Formal',
      descripcion: 'Traje formal oscuro con chaleco antibalas oculto',
      precio: 450,
      imagen: '👔'
    },
    {
      nombre: 'Uniforme Ejecutivo Casual',
      descripcion: 'Vestimenta casual profesional con protección',
      precio: 380,
      imagen: '👕'
    },
    {
      nombre: 'Uniforme Táctico Negro',
      descripcion: 'Uniforme táctico completo con placas balísticas',
      precio: 650,
      imagen: '🥋'
    },
    {
      nombre: 'Uniforme Táctico Camuflaje',
      descripcion: 'Uniforme militar con equipo completo',
      precio: 680,
      imagen: '🎖️'
    },
    {
      nombre: 'Uniforme Discreto Civil',
      descripcion: 'Ropa de civil con chaleco oculto',
      precio: 320,
      imagen: '👔'
    },
    {
      nombre: 'Uniforme de Gala',
      descripcion: 'Traje de etiqueta con protección integrada',
      precio: 550,
      imagen: '🤵'
    }
  ];

  // ============================================
  // ARMAMENTO - NUEVO
  // ============================================
  tiposArmamento: Armamento[] = [
    {
      tipo: 'Arma Corta',
      descripcion: 'Pistola semiautomática',
      calibre: '9mm / .40 / .45',
      imagen: '🔫'
    },
    {
      tipo: 'Fusil',
      descripcion: 'Fusil de asalto o carabina',
      calibre: '5.56mm / 7.62mm',
      imagen: '🔫'
    }
  ];

  // ============================================
  // CONTROL DE FLUJO
  // ============================================
  uniformSelectionStep: 'vehicle' | 'uniform' | 'armamento' = 'vehicle';
  pendingVehicleForUniform: any = null;
  pendingVehicleForArmamento: any = null; // ⬅️ NUEVO
  currentUniformIndex: number = 0;
  currentArmamentoIndex: number = 0; // ⬅️ NUEVO

  // ============================================
  // EQUIPAMIENTO
  // ============================================
  equipamientoDisponible = [
    { nombre: 'GPS Satelital Avanzado', precio: 800, seleccionado: false, icono: '📡' },
    { nombre: 'Sistema de Comunicación Encriptada', precio: 1200, seleccionado: false, icono: '📻' },
    { nombre: 'Detector de Amenazas', precio: 1500, seleccionado: false, icono: '🔍' },
    { nombre: 'Kit Médico Táctico', precio: 600, seleccionado: false, icono: '⚕️' },
    { nombre: 'Cámaras de Seguridad 360°', precio: 950, seleccionado: false, icono: '📹' },
    { nombre: 'Inhibidor de Señales', precio: 1800, seleccionado: false, icono: '📵' },
    { nombre: 'Sistema Anti-Seguimiento', precio: 2200, seleccionado: false, icono: '🛡️' },
    { nombre: 'Equipo de Visión Nocturna', precio: 1400, seleccionado: false, icono: '🔦' }
  ];

  // ============================================
  // FORMULARIO DE COTIZACIÓN
  // ============================================
  cotizacionForm: FormGroup;
  enviandoCotizacion = false;
  cotizacionEnviada = false;
  errorEnvio = false;

  constructor(
    private fb: FormBuilder,
    private http: HttpClient
  ) {
    this.cotizacionForm = this.fb.group({
      nombreCompleto: ['', [Validators.required, Validators.minLength(3)]],
      empresa: [''],
      email: ['', [Validators.required, Validators.email]],
      telefono: ['', [Validators.required, Validators.pattern(/^\d{10}$/)]],
      mensajeAdicional: ['']
    });
  }

  // ============================================
  // MÉTODOS DE VEHÍCULOS
  // ============================================
  incrementVehicle(tipo: string): void {
    if (this.vehicleCounts[tipo] < 10) {
      this.vehicleCounts[tipo]++;
    }
  }

  decrementVehicle(tipo: string): void {
    if (this.vehicleCounts[tipo] > 0) {
      this.vehicleCounts[tipo]--;
      this.selectedVehicles = this.selectedVehicles.filter(v => v.tipo !== tipo);
    }
  }

  confirmVehicleSelection(): void {
    const vehiculosConCantidad = Object.entries(this.vehicleCounts)
      .filter(([_, cantidad]) => cantidad > 0)
      .map(([tipo, _]) => tipo);

    if (vehiculosConCantidad.length === 0) {
      alert('Por favor, selecciona al menos un vehículo');
      return;
    }

    // Iniciar proceso de selección de uniformes
    this.uniformSelectionStep = 'uniform';
    this.procesarSiguienteVehiculo();
  }

  procesarSiguienteVehiculo(): void {
    const vehiculosPendientes = Object.entries(this.vehicleCounts)
      .filter(([tipo, cantidad]) => {
        const yaConfigurado = this.selectedVehicles.some(v => v.tipo === tipo);
        return cantidad > 0 && !yaConfigurado;
      });

    if (vehiculosPendientes.length > 0) {
      const [tipo, cantidad] = vehiculosPendientes[0];
      const vehicleInfo = this.vehicleTypes.find(v => v.tipo === tipo);
      
      this.pendingVehicleForUniform = {
        tipo,
        cantidad,
        tripulacion: vehicleInfo?.tripulacion || 2,
        categoria: vehicleInfo?.categoria || 'Ejecutivo'
      };
      this.currentUniformIndex = 0;
      this.uniformSelectionStep = 'uniform';
    } else {
      // Ya no hay vehículos pendientes, mostrar equipamiento
      this.uniformSelectionStep = 'vehicle';
    }
  }

  // ============================================
  // MÉTODOS DE UNIFORMES
  // ============================================
  selectUniform(uniforme: Uniform): void {
    if (!this.pendingVehicleForUniform) return;

    const vehicleIndex = this.selectedVehicles.findIndex(
      v => v.tipo === this.pendingVehicleForUniform.tipo
    );

    if (vehicleIndex === -1) {
      // Primera vez configurando este vehículo
      this.selectedVehicles.push({
        tipo: this.pendingVehicleForUniform.tipo,
        cantidad: this.pendingVehicleForUniform.cantidad,
        uniformes: [uniforme.nombre],
        armamento: [] // ⬅️ NUEVO: Inicializar array vacío
      });
    } else {
      // Ya existe, agregar uniforme
      this.selectedVehicles[vehicleIndex].uniformes.push(uniforme.nombre);
    }

    this.currentUniformIndex++;

    // Verificar si ya asignamos uniformes a toda la tripulación
    if (this.currentUniformIndex >= this.pendingVehicleForUniform.tripulacion) {
      // ⬅️ NUEVO: Pasar a selección de armamento
      this.uniformSelectionStep = 'armamento';
      this.pendingVehicleForArmamento = { ...this.pendingVehicleForUniform };
      this.currentArmamentoIndex = 0;
    }
  }

  // ============================================
  // MÉTODOS DE ARMAMENTO - NUEVO
  // ============================================
  selectArmamento(armamento: Armamento): void {
    if (!this.pendingVehicleForArmamento) return;

    const vehicleIndex = this.selectedVehicles.findIndex(
      v => v.tipo === this.pendingVehicleForArmamento.tipo
    );

    if (vehicleIndex !== -1) {
      this.selectedVehicles[vehicleIndex].armamento.push(armamento.tipo);
    }

    this.currentArmamentoIndex++;

    // Verificar si ya asignamos armamento a toda la tripulación
    if (this.currentArmamentoIndex >= this.pendingVehicleForArmamento.tripulacion) {
      // Terminar con este vehículo, procesar siguiente
      this.pendingVehicleForUniform = null;
      this.pendingVehicleForArmamento = null;
      this.procesarSiguienteVehiculo();
    }
  }

  cancelarSeleccionArmamento(): void {
    // Volver a selección de vehículos sin guardar armamento
    this.uniformSelectionStep = 'vehicle';
    this.pendingVehicleForArmamento = null;
    this.currentArmamentoIndex = 0;
  }

  // ============================================
  // MÉTODOS DE EQUIPAMIENTO
  // ============================================
  toggleEquipamiento(item: any): void {
    item.seleccionado = !item.seleccionado;
  }

  get equipamientoSeleccionado() {
    return this.equipamientoDisponible.filter(e => e.seleccionado);
  }

  get totalEquipamiento(): number {
    return this.equipamientoSeleccionado.reduce((sum, e) => sum + e.precio, 0);
  }

  // ============================================
  // CÁLCULOS
  // ============================================
  get totalVehiculos(): number {
    return Object.values(this.vehicleCounts).reduce((sum, count) => sum + count, 0);
  }

  get detalleVehiculos(): string {
    return Object.entries(this.vehicleCounts)
      .filter(([_, cantidad]) => cantidad > 0)
      .map(([tipo, cantidad]) => `${cantidad}x ${tipo}`)
      .join(', ');
  }

  // ============================================
  // VALIDACIONES FORMULARIO
  // ============================================
  get nombreValido(): boolean {
    const control = this.cotizacionForm.get('nombreCompleto');
    return control ? control.valid && control.touched : false;
  }

  get emailValido(): boolean {
    const control = this.cotizacionForm.get('email');
    return control ? control.valid && control.touched : false;
  }

  get telefonoValido(): boolean {
    const control = this.cotizacionForm.get('telefono');
    return control ? control.valid && control.touched : false;
  }

  // ============================================
  // ENVIAR COTIZACIÓN
  // ============================================
  enviarCotizacion(): void {
    if (this.cotizacionForm.invalid) {
      Object.keys(this.cotizacionForm.controls).forEach(key => {
        this.cotizacionForm.get(key)?.markAsTouched();
      });
      return;
    }

    this.enviandoCotizacion = true;
    this.errorEnvio = false;

    const fechaActual = new Date();
    const cotizacionData = {
      // Datos del cliente
      ...this.cotizacionForm.value,
      
      // Datos del servicio
      servicio: 'Protección Ejecutiva',
      totalVehiculos: this.totalVehiculos,
      vehiculos: this.selectedVehicles, // ⬅️ Ahora incluye armamento
      equipamiento: this.equipamientoSeleccionado.map(e => e.nombre),
      
      // Metadata
      fecha: fechaActual.toLocaleDateString('es-EC'),
      hora: fechaActual.toLocaleTimeString('es-EC')
    };

    this.http.post('http://localhost:3000/api/cotizacion', cotizacionData)
      .subscribe({
        next: (response) => {
          console.log('Cotización enviada exitosamente:', response);
          this.enviandoCotizacion = false;
          this.cotizacionEnviada = true;
          
          setTimeout(() => {
            this.cotizacionEnviada = false;
            this.resetearFormulario();
          }, 3000);
        },
        error: (error) => {
          console.error('Error al enviar cotización:', error);
          this.enviandoCotizacion = false;
          this.errorEnvio = true;
          
          setTimeout(() => {
            this.errorEnvio = false;
          }, 5000);
        }
      });
  }

  resetearFormulario(): void {
    this.cotizacionForm.reset();
    this.vehicleCounts = {
      'Sedan': 0,
      'SUV': 0,
      'Todo Terreno': 0,
      'Camioneta': 0,
      'Hatchback': 0,
      'Motocicleta': 0,
      'Helicóptero': 0
    };
    this.selectedVehicles = [];
    this.equipamientoDisponible.forEach(e => e.seleccionado = false);
    this.uniformSelectionStep = 'vehicle';
  }
}
